const request = $input.first().json.body;
const isClosedObject = request !== null && typeof request === 'object' && !Array.isArray(request) && Object.keys(request).length === 1 && Object.hasOwn(request, 'correlation_id');
const correlationId = isClosedObject && typeof request.correlation_id === 'string' ? request.correlation_id : '';
const validCorrelationId = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/.test(correlationId);

if (!validCorrelationId) {
  return [{ json: { http_status: 400, response: { correlation_id: 'unavailable', redacted_error: { code: 'INVALID_REQUEST', message: 'The request could not be accepted.' } } } }];
}

return [{ json: { http_status: 200, response: { correlation_id: correlationId, result: { status: 'accepted' } } } }];
